import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { router } from 'kea-router'
import posthog from 'posthog-js'

import { teamLogic } from 'scenes/teamLogic'
import { urls } from 'scenes/urls'

import type { AttachedContextItem } from '~/layout/ai/attachedContext'
import { attachedContextLogic } from '~/layout/ai/attachedContextLogic'

import type { ComposerPrefillRequest } from 'products/posthog_ai/frontend/api/runner'

import { SAMPLE_NEWS_EDITION, type TodayNewsEdition, type TodayNewsStory } from './todayNewsEdition'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayNewsLogicValues {
    currentProjectId: number | string // teamLogic
    composerFocusRequest: number
    composerPrefill: ComposerPrefillRequest | null
    divedStoryId: string | null
    edition: TodayNewsEdition
    hasUnreadNews: boolean
    isNewsOpen: boolean
    readEditionIds: Record<string, string>
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayNewsLogicActions {
    pickItem: (
        item: AttachedContextItem,
        taskId?: string | undefined
    ) => {
        item: AttachedContextItem
        taskId: string
    } // attachedContextLogic
    closeNews: () => {
        value: true
    }
    diveIn: (
        story: TodayNewsStory,
        position: number
    ) => {
        position: number
        story: TodayNewsStory
    }
    homeTaskStarted: (taskId: string) => {
        taskId: string
    }
    markEditionRead: (
        projectId: string,
        editionId: string
    ) => {
        editionId: string
        projectId: string
    }
    openNews: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayNewsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        hasUnreadNews: (
            readEditionIds: Record<string, string>,
            currentProjectId: number | string,
            edition: TodayNewsEdition
        ) => boolean
    }
}

export type todayNewsLogicType = MakeLogicType<
    todayNewsLogicValues,
    todayNewsLogicActions,
    Record<string, any>,
    todayNewsLogicMeta
>

export const todayNewsLogic = kea<todayNewsLogicType>([
    path(['scenes', 'project-homepage', 'today', 'todayNewsLogic']),
    connect(() => ({
        values: [teamLogic, ['currentProjectId']],
        actions: [attachedContextLogic, ['pickItem']],
    })),
    actions({
        openNews: true,
        closeNews: true,
        diveIn: (story: TodayNewsStory, position: number) => ({ story, position }),
        markEditionRead: (projectId: string, editionId: string) => ({ projectId, editionId }),
        homeTaskStarted: (taskId: string) => ({ taskId }),
    }),
    reducers({
        isNewsOpen: [
            false,
            {
                openNews: () => true,
                closeNews: () => false,
                diveIn: () => false,
            },
        ],
        readEditionIds: [
            {} as Record<string, string>,
            { persist: true },
            {
                markEditionRead: (state, { projectId, editionId }) => ({ ...state, [projectId]: editionId }),
            },
        ],
        composerPrefill: [
            null as ComposerPrefillRequest | null,
            {
                diveIn: (_, { story }) => ({ prompt: story.divePrompt }),
            },
        ],
        composerFocusRequest: [
            0,
            {
                diveIn: (state) => state + 1,
            },
        ],
        divedStoryId: [
            null as string | null,
            {
                diveIn: (_, { story }) => story.id,
            },
        ],
    }),
    selectors({
        edition: [() => [], (): TodayNewsEdition => SAMPLE_NEWS_EDITION],
        hasUnreadNews: [
            (s) => [s.readEditionIds, s.currentProjectId, s.edition],
            (
                readEditionIds: Record<string, string>,
                currentProjectId: number | string,
                edition: TodayNewsEdition
            ): boolean => readEditionIds[String(currentProjectId)] !== edition.id,
        ],
    }),
    listeners(({ actions, values }) => ({
        openNews: () => {
            posthog.capture('today news opened', {
                edition_id: values.edition.id,
                sample: values.edition.isSample,
                had_unread: values.hasUnreadNews,
            })
            actions.markEditionRead(String(values.currentProjectId), values.edition.id)
        },
        diveIn: ({ story, position }) => {
            posthog.capture('today news dive in', {
                edition_id: values.edition.id,
                story_id: story.id,
                product: story.product,
                position,
            })
            actions.pickItem({
                type: 'text',
                key: `today-news-${story.id}`,
                label: story.title,
                value: `${story.title}. ${story.summary}`,
            })
        },
        homeTaskStarted: ({ taskId }) => {
            posthog.capture('today home task started', { from_news_story_id: values.divedStoryId })
            router.actions.push(urls.aiTask(taskId))
        },
    })),
])
